const stripHtml = (value) => String(value ?? '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();

const headerValue = (headers, wantedName) => {
  if (!headers) return '';
  const wanted = wantedName.toLowerCase();
  if (Array.isArray(headers)) {
    const match = headers.find((header) =>
      String(header.name ?? header.key ?? '').toLowerCase() === wanted
    );
    return match?.value ?? '';
  }
  if (typeof headers === 'object') {
    const key = Object.keys(headers).find((name) => name.toLowerCase() === wanted);
    const value = key ? headers[key] : '';
    return Array.isArray(value) ? value.join(', ') : value;
  }
  return '';
};

const parseAddress = (raw) => {
  if (!raw) return { name: '', email: '' };

  if (typeof raw === 'object') {
    const first = raw.value?.[0] ?? (Array.isArray(raw) ? raw[0] : raw);
    if (first && typeof first === 'object' && first.address) {
      return {
        name: String(first.name ?? '').trim(),
        email: String(first.address).trim().toLowerCase(),
      };
    }
    if (raw.text) raw = raw.text;
  }

  const text = String(raw);
  const angleMatch = text.match(/^(.*?)<([^<>\s]+@[^<>\s]+)>/);
  const emailMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  const email = (angleMatch?.[2] ?? emailMatch?.[0] ?? '').trim().toLowerCase();
  const name = (angleMatch?.[1] ?? text.replace(email, ''))
    .replace(/["']/g, '')
    .trim();
  return { name, email };
};

return $input.all().map((item) => {
  const input = item.json;
  const headers = input.headers ?? input.payload?.headers;
  const from = parseAddress(input.from ?? headerValue(headers, 'from'));
  const replyTo = parseAddress(input.replyTo ?? input['reply-to'] ?? headerValue(headers, 'reply-to'));
  const messageId = String(input.id ?? input.messageId ?? '').trim();

  if (!messageId) {
    throw new Error('Gmail Trigger output did not contain a Gmail message ID.');
  }

  const subject = String(input.subject ?? headerValue(headers, 'subject') ?? '(no subject)').trim();
  const bodyCandidates = [input.textPlain, input.text, input.body, input.snippet, input.html];
  const rawBody = bodyCandidates.find((value) => value != null && String(value).trim()) ?? '';
  const body = input.html === rawBody ? stripHtml(rawBody) : String(rawBody).trim();
  const maxBodyLength = 12000;

  let receivedAt = input.date ?? input.receivedAt ?? input.internalDate ?? headerValue(headers, 'date') ?? '';
  if (/^\d+$/.test(String(receivedAt))) {
    receivedAt = new Date(Number(receivedAt)).toISOString();
  } else if (receivedAt && !Number.isNaN(Date.parse(String(receivedAt)))) {
    receivedAt = new Date(String(receivedAt)).toISOString();
  } else {
    receivedAt = String(receivedAt);
  }

  const binaryAttachments = Object.values(item.binary ?? {})
    .map((attachment) => attachment.fileName)
    .filter(Boolean);
  const parsedAttachments = Array.isArray(input.attachments)
    ? input.attachments.map((attachment) => attachment.filename ?? attachment.fileName).filter(Boolean)
    : [];

  return {
    json: {
      message_id: messageId,
      thread_id: String(input.threadId ?? '').trim(),
      received_at: receivedAt,
      sender_name: from.name,
      sender_email: from.email,
      reply_to_email: replyTo.email || from.email,
      subject,
      body: body.slice(0, maxBodyLength),
      body_truncated: body.length > maxBodyLength,
      attachment_names: [...new Set([...binaryAttachments, ...parsedAttachments])],
      gmail_url: `https://mail.google.com/mail/u/0/#inbox/${messageId}`,
    },
    pairedItem: item.pairedItem,
  };
});

const categories = new Set(['urgent', 'customer_support', 'sales', 'billing', 'scheduling', 'internal', 'newsletter', 'spam', 'other']);
const priorities = new Set(['high', 'medium', 'low']);
const sentiments = new Set(['positive', 'neutral', 'negative']);
const suppressedCategories = new Set(['newsletter', 'spam']);

const clean = (value, maxLength = 8000) => String(value ?? '')
  .replace(/\u0000/g, '')
  .trim()
  .slice(0, maxLength);

return $input.all().map((item) => {
  const data = item.json;
  let content = data.choices?.[0]?.message?.content;
  if (Array.isArray(content)) {
    content = content.map((part) => part.text ?? '').join('');
  }
  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('The LLM response did not contain choices[0].message.content.');
  }

  content = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  let result;
  try {
    result = JSON.parse(content);
  } catch (error) {
    throw new Error(`The LLM returned invalid JSON: ${error.message}`);
  }

  if (!categories.has(result.category)) throw new Error(`Invalid category: ${result.category}`);
  if (!priorities.has(result.priority)) throw new Error(`Invalid priority: ${result.priority}`);
  if (!sentiments.has(result.sentiment)) throw new Error(`Invalid sentiment: ${result.sentiment}`);

  const confidence = Number(result.confidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    throw new Error(`Invalid confidence: ${result.confidence}`);
  }

  const summary = clean(result.summary, 1000);
  if (!summary) throw new Error('The LLM returned an empty summary.');

  const localPart = String(data.reply_to_email ?? '').split('@')[0];
  const automatedSender = /(?:^|[._+-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster)(?:$|[._+-])/i.test(localPart);
  const requiresResponse = result.requires_response === true;
  const draftBody = clean(result.draft_body);
  const shouldCreateDraft = requiresResponse
    && !suppressedCategories.has(result.category)
    && !automatedSender
    && Boolean(data.reply_to_email)
    && Boolean(draftBody)
    && confidence >= 0.55;

  const originalSubject = clean(data.subject, 500);
  const suggestedSubject = clean(result.draft_subject, 500);
  const draftSubject = shouldCreateDraft
    ? (suggestedSubject || (originalSubject.toLowerCase().startsWith('re:') ? originalSubject : `Re: ${originalSubject}`))
    : '';

  return {
    json: {
      message_id: data.message_id,
      thread_id: data.thread_id,
      received_at: data.received_at,
      sender_name: data.sender_name,
      sender_email: data.sender_email,
      reply_to_email: data.reply_to_email,
      subject: originalSubject,
      gmail_url: data.gmail_url,
      category: result.category,
      priority: result.priority,
      sentiment: result.sentiment,
      confidence,
      summary,
      classification_reason: clean(result.reason, 1000),
      requires_response: requiresResponse,
      should_create_draft: shouldCreateDraft,
      draft_subject: draftSubject,
      draft_body: shouldCreateDraft ? draftBody : '',
    },
    pairedItem: item.pairedItem,
  };
});

const isNoDraftPath = Boolean($json.message_id);
const triage = isNoDraftPath ? $json : $('Validate AI Result').item.json;
const draftId = isNoDraftPath ? '' : String($json.id ?? '');
const draftCreated = Boolean(draftId);

let status = 'no_response_needed';
if (draftCreated) {
  status = 'draft_created';
} else if (triage.requires_response) {
  status = 'manual_review';
}

return {
  json: {
    processed_at: new Date().toISOString(),
    message_id: triage.message_id,
    thread_id: triage.thread_id,
    received_at: triage.received_at,
    sender_name: triage.sender_name,
    sender_email: triage.sender_email,
    subject: triage.subject,
    category: triage.category,
    priority: triage.priority,
    sentiment: triage.sentiment,
    confidence: triage.confidence,
    summary: triage.summary,
    classification_reason: triage.classification_reason,
    requires_response: triage.requires_response,
    draft_created: draftCreated,
    draft_id: draftId,
    draft_subject: triage.draft_subject,
    draft_body: triage.draft_body,
    status,
    gmail_url: triage.gmail_url,
  },
};
